+template <>
+inline void storeFP32<c10::BFloat16>(float v, c10::BFloat16* ptr) {
+#ifdef ARM_BF16_SUPPORT
+  *reinterpret_cast<__bf16*>(ptr) = vcvth_bf16_f32(v);
+#else
+  *ptr = static_cast<c10::BFloat16>(v);
+#endif
+};
